    "isElement": true,
    "className": "MenuItemComponent",
    "status": "stable",
    "importName": "MenuItemComponent",
    "importPath": "@ids-group-ltd/ids-design-system",
    "summary": null,
    "inputs": [
      {
        "name": "icon",
        "kind": "input",
        "type": "IconName | null",
        "union": null,
        "default": "null",
        "required": false,
        "description": "Leading icon shown before the projected label."
      },
      {
        "name": "disabled",
        "kind": "input",
        "type": "boolean",
        "union": null,
        "default": "false",
        "required": false,
        "description": "Blocks activation and styles the item as inactive. It stays keyboard-focusable (`aria-disabled`, ARIA menu practice) and in `ds-menu`'s roving order, so a `[dsTooltip]` explaining why can be reached and shown."
      },
      {
        "name": "error",
        "kind": "input",
        "type": "boolean",
        "union": null,
        "default": "false",
        "required": false,
        "description": "Renders the item in an error/destructive style."
      },
      {
        "name": "quiet",
        "kind": "input",
        "type": "boolean",
        "union": null,
        "default": "false",
        "required": false,
        "description": "Renders the item muted — a secondary row like \"Sign out\" under a divider, still actionable but not competing with the items above it."
      },
      {
        "name": "description",
        "kind": "input",
        "type": "string",
        "union": null,
        "default": "''",
        "required": false,
        "description": "A standing second line under the label — a limitation the action carries (\"will not be saved\", \"read-only in this workspace\"). Visible without hover or focus, which is what separates it from a `[dsTooltip]`. Reaches assistive tech as `aria-describedby`, NOT as part of the item's name: the projected label names the action, and a caveat is a description of it. That is why the line is `aria-hidden` in the DOM and referenced by id — inside the button and visible, it would otherwise be concatenated into the name."
      },
      {
        "name": "submenu",
        "kind": "input",
        "type": "TemplateRef<unknown> | null",
        "union": null,
        "default": "null",
        "required": false,
        "description": "Optional submenu template — renders a nested `ds-menu` on hover / ArrowRight."
      }
    ],
