  "radio": {
    "key": "radio",
    "selector": "ds-radio",
    "isElement": true,
    "className": "RadioComponent",
    "status": "stable",
    "importName": "RadioComponent",
    "importPath": "@ids-group-ltd/ids-design-system",
    "summary": null,
    "inputs": [
      {
        "name": "hint",
        "kind": "input",
        "type": "string",
        "union": null,
        "default": "''",
        "required": false,
        "description": "Helper text shown below the control."
      },
      {
        "name": "error",
        "kind": "input",
        "type": "string",
        "union": null,
        "default": "''",
        "required": false,
        "description": "Error text. Shown immediately — binding it says the consumer has already decided this is in error. Takes precedence over `errors`."
      },
      {
        "name": "warning",
        "kind": "input",
        "type": "string",
        "union": null,
        "default": "''",
        "required": false,
        "description": "Advisory text, shown when there is no error."
      },
      {
        "name": "reserveMessage",
        "kind": "input",
        "type": "boolean | null",
        "union": null,
        "default": "null",
        "required": false,
        "description": "Reserve the message-row height even when empty, so the control doesn't shift the layout below it when a hint/error appears. What an unset value falls back to is the subclass's call, in `reserveMessageResolved`: a field takes `DS_CONFIG.field.reserveMessage`, a button does not."
      },
      {
        "name": "messageIcon",
        "kind": "input",
        "type": "IconName | false | null",
        "union": null,
        "default": "null",
        "required": false,
        "description": "Glyph on the message line, overriding what the state resolves to. Unset follows `DS_CONFIG.field.stateIcons`; `false` removes the glyph here alone."
      },
      {
        "name": "errors",
        "kind": "input",
        "type": "readonly DsFieldError[]",
        "union": null,
        "default": "[]",
        "required": false,
        "description": "Validation errors, shown once the user has interacted. Bound automatically by signal forms; reactive and template-driven forms are read through `NgControl` and need nothing here. Accepts a string, one error, or an array."
      },
      {
        "name": "invalid",
        "kind": "input",
        "type": "boolean",
        "union": null,
        "default": "false",
        "required": false,
        "description": "Paints the error state and sets `aria-invalid`, WITHOUT a message of its own — for when the text lives elsewhere, such as a form-level error summary or one message covering a whole field group. Use `error` to show text."
      },
      {
        "name": "touched",
        "kind": "input",
        "type": "boolean",
        "union": null,
        "default": "false",
        "required": false,
        "description": "Whether the user has interacted with the field. Bound by signal forms; gates `errors`, so a `required` error does not greet an untouched form."
      },
      {
        "name": "checked",
        "kind": "model",
        "type": "boolean",
        "union": null,
        "default": "false",
        "required": false,
        "description": "The ONLY way to drive a lone radio: this is deliberately not a `ControlValueAccessor`, so `[formControl]` and `ngModel` do not bind to it — inside `ds-radio-group` the GROUP is the form control, and a second accessor on one option would fight it. Inside a group this input is not read at all."
      },
      {
        "name": "deselectable",
        "kind": "input",
        "type": "boolean",
        "union": null,
        "default": "false",
        "required": false,
        "description": "Lets a checked standalone radio be cleared by clicking it again. Off by default, and ignored inside `ds-radio-group`: there a radio is one option of a choice, and clearing it would leave the group with no value through a gesture the group cannot see."
      },
      {
        "name": "disabled",
        "kind": "input",
        "type": "boolean",
        "union": null,
        "default": "false",
        "required": false,
        "description": "A disabled parent `ds-radio-group` also disables it, whatever this is set to."
      },
      {
        "name": "name",
        "kind": "input",
        "type": "string",
        "union": null,
        "default": "''",
        "required": false,
        "description": "Native `name` attribute — overridden by the group's name when inside `ds-radio-group`."
      },
      {
        "name": "value",
        "kind": "input",
        "type": "unknown",
        "union": null,
        "default": "''",
        "required": false,
        "description": "Value compared against the group's selection when inside `ds-radio-group`."
      },
      {
        "name": "inputId",
        "kind": "input",
        "type": "string | null",
        "union": null,
        "default": "null",
        "required": false,
        "description": "Overrides the auto-generated id used for the input and its label's `for`."
      },
      {
        "name": "size",
        "kind": "input",
        "type": "DsSize | null",
        "union": [
          "sm",
          "md",
          "lg"
        ],
        "default": "null",
        "required": false,
        "description": "Unset falls back to `DS_CONFIG.control.size`, then `'md'`."
      },
      {
        "name": "required",
        "kind": "input",
        "type": "boolean",
        "union": null,
        "default": "false",
        "required": false,
        "description": "Marks the radio required — shows an asterisk on the label and sets `aria-required`."
      },
      {
        "name": "label",
        "kind": "input",
        "type": "string",
        "union": null,
        "default": "''",
        "required": false,
        "description": "Inline label rendered beside the dot and wired via for/id. Omit to bring your own <label>."
      },
      {
        "name": "ariaLabel",
        "kind": "input",
        "type": "string | null",
        "union": null,
        "default": "null",
        "required": false,
        "description": "Accessible name for a control with no visible label — the row's `<label>` collapses when it is empty, leaving nothing to name it. Set beside a label it OVERRIDES the label, per ARIA."
      }
    ],
    "outputs": []
  },
